/// <summary>
/// Extension class for <c>LogisticsPostalAddressElectronicContactV2Entity</c> table.
/// Adds validation and location assignment logic for customer and vendor accounts.
/// </summary>
[ExtensionOf(tableStr(LogisticsPostalAddressElectronicContactV2Entity))]
public final class AVARUMLogisticsPostalAddressElectronicContactV2Entity_Extension
{
}

Method.Source:
/// <summary>
/// Validates the specified field for the entity.
/// Ensures only one of <c>AVACustomerAccount</c> or <c>AVAVendorAccount</c> is set,
/// and that <c>PostalAddressLocationId</c> is present if neither account is set.
/// </summary>
/// <param name="_fieldIdToCheck">The field ID to validate.</param>
/// <returns>True if validation passes; otherwise, throws an error.</returns>
public boolean validateField(FieldId _fieldIdToCheck)
{
    switch (_fieldIdToCheck)
    {
        case fieldNum(LogisticsPostalAddressElectronicContactV2Entity, AVACustomerAccount):
        case fieldNum(LogisticsPostalAddressElectronicContactV2Entity, AVAVendorAccount):
        case fieldNum(LogisticsPostalAddressElectronicContactV2Entity, PostalAddressLocationId):
            this.validateData();
            break;
    }

    return next validateField(_fieldIdToCheck);
}

/// <summary>
/// Persists the entity data.
/// Skips validation of <c>PostalAddressLocationId</c> if neither customer nor vendor account is set.
/// </summary>
/// <param name="_entityCtx">The entity runtime context.</param>
public void persistEntity(DataEntityRuntimeContext _entityCtx)
{
    if (!this.AVACustomerAccount && !this.AVAVendorAccount)
    {
        _entityCtx.getEntityRecord().skipDataSourceValidateField(fieldNum(LogisticsPostalAddressElectronicContactV2Entity, PostalAddressLocationId), false);
    }

    next persistEntity(_entityCtx);
}

/// <summary>
/// Initializes the entity data source.
/// Validates data and sets location fields based on account type.
/// </summary>
/// <param name="_entityCtx">The entity runtime context.</param>
/// <param name="_dataSourceCtx">The data source runtime context.</param>
public void initializeEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(LogisticsPostalAddressElectronicContactV2Entity, LogisticsLocation))
    {
        this.validateData();

        AccountNum accountNum = this.AVACustomerAccount ? this.AVACustomerAccount : this.AVAVendorAccount;
        AVARUMLogisticsLocationPartyType partyType = this.AVACustomerAccount ? AVARUMLogisticsLocationPartyTypeId::Customer : AVARUMLogisticsLocationPartyTypeId::Vendor;
        LogisticsLocation logisticsLocation = LogisticsPostalAddressElectronicContactV2Entity::findLogisticsLocation(partyType, accountNum);

        if (logisticsLocation)
        {
            _dataSourceCtx.setBuffer(logisticsLocation);
            this.LocationId = logisticsLocation.LocationId;
            this.PostalAddressLocationId = logisticsLocation.LocationId;
        }
    }

    next initializeEntityDataSource(_entityCtx, _dataSourceCtx);
}

/// <summary>
/// Validates that only one of <c>AVACustomerAccount</c> or <c>AVAVendorAccount</c> is set,
/// and that <c>PostalAddressLocationId</c> is present if neither account is set.
/// </summary>
/// <returns>True if validation passes; otherwise, throws an error.</returns>
private boolean validateData()
{
    if (this.AVACustomerAccount && this.AVAVendorAccount)
    {
        throw Global::error("@AVARUM:BothCustomerAndVendorAccountsAreSetOnlyOneIsAllowed");
    }
    else if (!this.AVACustomerAccount && !this.AVAVendorAccount && !this.PostalAddressLocationId)
    {
        throw Global::error(strFmt("@SYS110217", "@GlobalAddressBook:LogisticsPostalAddressElectronicContactPostalAddressLocationId"));
    }

    return true;
}

/// <summary>
/// Finds the logistics location for the specified party type and account number.
/// Throws an error if not found and <c>_throwError</c> is true.
/// </summary>
/// <param name="partyType">The party type (Customer or Vendor).</param>
/// <param name="accountNum">The account number.</param>
/// <param name="_throwError">Whether to throw an error if not found.</param>
/// <returns>The logistics location record, or null if not found.</returns>
internal static LogisticsLocation findLogisticsLocation(AVARUMLogisticsLocationPartyType partyType, AccountNum accountNum, boolean _throwError = true)
{
    DirPartyLocation dirPartyLocation;
    LogisticsLocation logisticsLocation;
    DirPartyTable dirPartyTable;
    DirPartyRecId partyRecId;

    switch (partyType)
    {
        case AVARUMLogisticsLocationPartyTypeId::Customer:
            CustTable custTable = CustTable::find(accountNum);

            if (!custTable)
            {
                throw Global::error(strFmt("@SYS16734", accountNum));
            }

            partyRecId = custTable.Party;
            break;

        case AVARUMLogisticsLocationPartyTypeId::Vendor:
            VendTable vendTable = VendTable::find(accountNum);

            if (!vendTable)
            {
                throw Global::error(strFmt("@SYS16734", accountNum));
            }

            partyRecId = vendTable.Party;
            break;

        default:
            throw Global::error(strFmt("@AVARUM:InvalidPartyType", partyType));
    }

    select firstonly logisticsLocation
            exists join dirPartyLocation
                where dirPartyLocation.Location == logisticsLocation.RecId &&
                    dirPartyLocation.IsPostalAddress == NoYes::No
            join DirPartyTable
                where DirPartyTable.RecId == dirPartyLocation.Party &&
                    dirPartyLocation.Party == partyRecId;

    if (!logisticsLocation && _throwError)
    {
        throw Global::error(strFmt("@AVARUM:NoAddressLocationForTheGivenPartyTypeFound", accountNum, partyType));
    }

    return logisticsLocation;
}

/// <summary>
/// Updates staging data with location information after data import.
/// </summary>
/// <param name="_dmfDefinitionGroupExecution">The DMF definition group execution context.</param>
public static void postGetStagingData(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    LogisticsPostalAddressElectronicContactV2Staging stagingData;

    ttsbegin;

    while select forupdate stagingData
        where stagingData.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId &&
            stagingData.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
    {
        AccountNum accountNum = stagingData.AVACustomerAccount ? stagingData.AVACustomerAccount : stagingData.AVAVendorAccount;
        AVARUMLogisticsLocationPartyType partyType = stagingData.AVACustomerAccount ? AVARUMLogisticsLocationPartyTypeId::Customer : AVARUMLogisticsLocationPartyTypeId::Vendor;
        LogisticsLocation logisticsLocation = LogisticsPostalAddressElectronicContactV2Entity::findLogisticsLocation(partyType, accountNum);

        if (logisticsLocation)
        {
            stagingData.LocationId = logisticsLocation.LocationId;
            stagingData.PostalAddressLocationId = logisticsLocation.LocationId;
            stagingData.doUpdate();
        }
    }

    ttscommit;
}
